inline uint8_t fp01_byte(size_t offset, uint8_t stock) {
  if (offset >= 0xd3e0 && offset < 0xd3e0 + sizeof(FP01_DESCRIPTOR)) return FP01_DESCRIPTOR[offset - 0xd3e0];
  if (offset >= 0xc08 && offset < 0xc08 + sizeof(FP01_HOOK_SOUND)) return FP01_HOOK_SOUND[offset - 0xc08];
  if (offset >= 0x5e5e && offset < 0x5e5e + sizeof(FP01_HOOK_SLEEP)) return FP01_HOOK_SLEEP[offset - 0x5e5e];
  if (offset >= 0x6c02 && offset < 0x6c02 + sizeof(FP01_HOOK_INIT)) return FP01_HOOK_INIT[offset - 0x6c02];
  if (offset >= 0x6c34 && offset < 0x6c34 + sizeof(FP01_HOOK_ROUTE)) return FP01_HOOK_ROUTE[offset - 0x6c34];
  if (offset >= 0x6c52 && offset < 0x6c52 + sizeof(FP01_HOOK_TICK)) return FP01_HOOK_TICK[offset - 0x6c52];
  if (offset >= 0x5df4 && offset < 0x5df4 + sizeof(FP01_HOOK_BOOT)) return FP01_HOOK_BOOT[offset - 0x5df4];
  if (offset >= 0x7810 && offset < 0x7810 + sizeof(FP01_CANDIDATE)) return FP01_CANDIDATE[offset - 0x7810];
  return rs01_byte(offset, stock);
}
inline bool apply_platform(uint8_t *image, size_t size) {
  if (!image || size != IMAGE_SIZE) return false;
  const uint8_t before_hook_sound[] = {0xf8,0xb5,0x31,0x4d,0x04,0x46,0x0f,0x46};
  if (std::memcmp(image + 0xc08, before_hook_sound, sizeof(before_hook_sound))) return false;
  const uint8_t before_hook_sleep[] = {0xfe,0xf7,0x83,0xff};
  if (std::memcmp(image + 0x5e5e, before_hook_sleep, sizeof(before_hook_sleep))) return false;
  const uint8_t before_hook_init[] = {0x00,0xf0,0x4d,0xf8};
  if (std::memcmp(image + 0x6c02, before_hook_init, sizeof(before_hook_init))) return false;
  const uint8_t before_hook_route[] = {0x00,0xf0,0xd4,0xf9};
  if (std::memcmp(image + 0x6c34, before_hook_route, sizeof(before_hook_route))) return false;
  const uint8_t before_hook_tick[] = {0x00,0xf0,0x35,0xf8};
  if (std::memcmp(image + 0x6c52, before_hook_tick, sizeof(before_hook_tick))) return false;
  const uint8_t before_hook_boot[] = {0xfc,0xf7,0x50,0xfa};
  if (std::memcmp(image + 0x5df4, before_hook_boot, sizeof(before_hook_boot))) return false;
  for (size_t i = 0x7810; i < IMAGE_SIZE; ++i) if (image[i] != 255) return false;
  std::memcpy(image + 0xd3e0, FP01_DESCRIPTOR, sizeof(FP01_DESCRIPTOR));
  std::memcpy(image + 0xc08, FP01_HOOK_SOUND, sizeof(FP01_HOOK_SOUND));
  std::memcpy(image + 0x5e5e, FP01_HOOK_SLEEP, sizeof(FP01_HOOK_SLEEP));
  std::memcpy(image + 0x6c02, FP01_HOOK_INIT, sizeof(FP01_HOOK_INIT));
  std::memcpy(image + 0x6c34, FP01_HOOK_ROUTE, sizeof(FP01_HOOK_ROUTE));
  std::memcpy(image + 0x6c52, FP01_HOOK_TICK, sizeof(FP01_HOOK_TICK));
  std::memcpy(image + 0x5df4, FP01_HOOK_BOOT, sizeof(FP01_HOOK_BOOT));
  std::memcpy(image + 0x7810, FP01_CANDIDATE, sizeof(FP01_CANDIDATE));
  return true;
}
